def _scene() -> Image.Image:
    im = Image.new("RGB", (1200, 900), (232, 228, 218))
    d = ImageDraw.Draw(im)
    d.rectangle((80, 80, 1120, 820), outline=(90, 90, 90), width=6)
    d.rectangle((140, 520, 560, 760), fill=(160, 120, 80))       # 书桌
    d.rectangle((180, 560, 300, 640), fill=(110, 80, 50))        # 抽屉
    d.rectangle((700, 150, 1060, 500), fill=(200, 200, 215))     # 床
    d.ellipse((620, 600, 700, 680), fill=(70, 70, 70))           # 椅子
    f = C.pil_font(34, "hei")
    d.text((190, 660), "书桌（抽屉）", font=f, fill=(250, 250, 250))
    d.text((800, 300), "床", font=f, fill=(60, 60, 60))
    d.text((100, 30), "302室平面示意（非比例）", font=f, fill=(40, 40, 40))
    return im


def build(root: Path) -> None:
    d = root / CASE
    d.mkdir(parents=True, exist_ok=True)
    C.text_pdf(d / "起诉意见书.pdf", QISU, FEAT)

    pages = []
    for i, text in enumerate(XUNWEN):
        im = C.render_page(text, seed=100 + i)
        im = C.add_watermark(im, "仅供办案使用")
        if i == 1:
            im = C.add_handwriting(im, (560, 1420), "此处与银行流水核对", seed=11)
        if i == 2:
            im = C.add_seal(im, (900, 1380), "虚构市公安局虚构区分局")
        pages.append(im)
    C.image_pdf(d / "讯问笔录.pdf", pages, FEAT)

    C.mixed_pdf(d / "现场勘验图文.pdf", MIXED_TEXT, _scene(), FEAT)
    C.save_jpeg(C.screenshot_image(SCREENSHOT_LINES), d / "转账截图.jpg", FEAT)
